#include <Arduino.h>

// Reliable software servo implementation for simulation
class SoftServo {
  int pin;
  int angle = 90;
public:
  void attach(int p) { pin = p; pinMode(pin, OUTPUT); }
  void write(int a) { angle = constrain(a, 0, 180); }
  void refresh() {
    int pulseUs = map(angle, 0, 180, 544, 2400);
    digitalWrite(pin, HIGH);
    delayMicroseconds(pulseUs);
    digitalWrite(pin, LOW);
    // Simulation automatically handles the 'rest' time when we return to loop.
  }
};

SoftServo myServo;
static const int SERVO_PIN = 15;
static const int POT_PIN = A0;

void setup() {
  myServo.attach(SERVO_PIN);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Serial1.println("SERVO_POT_BOOT");
}

void loop() {
  const int raw = analogRead(POT_PIN);
  const int angle = map(raw, 0, 1023, 0, 180);
  myServo.write(angle);
  myServo.refresh();

  static int lastAngle = -1;
  if (abs(angle - lastAngle) > 2) {
    Serial1.print("SERVO_RAW=");
    Serial1.print(raw);
    Serial1.print(" ANG=");
    Serial1.println(angle);
    lastAngle = angle;
  }

  // Refresh every 20ms for standard servo timing
  delay(20);
}

